head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[radio > P > validator]<br/>컴포넌트에서 포커스가 해제될때 입력값 검증을 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [        
        "validate(), validateObject() 메소드로 유효성 체크에 실패했을때도 validator 속성의 사용자 정의 함수가 실행됩니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        validator: con_validator.getText(),      
        tabIndex: 1,
        mandatory: true,
    }

    let cList = $c.gcm.createCList(properties);    

    // target 생성
    $c.gcm.createLabel('label="validator 설정된 상태에서 validate, validateObjerct 실행 시 excuted validator 출력 되어야 함"', '', 'label1');
    $c.gcm.createBasicCheckBox(cList);
}



scwin.fn_validator = function(val, id) { 
    wf_body_bottom.getObj("scwin").setReturnValue("executed validator");
}



scwin.btn_validate_onclick = function (e) {
    let rtn = target1.validate();

    if (rtn) 
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
};



scwin.btn_validateObject_onclick = function (e) {
    let rtnObj  = target1.validateObject();
    wf_body_bottom.getObj("scwin").setReturnValue("validateObject : "+ rtnObj);

    if (rtnObj) {
        let callerId = rtnObj.callerId
        let type = rtnObj.type
        let value = rtnObj.value

        wf_body_bottom.getObj("scwin").setReturnValue("callerId : "+ callerId);
        wf_body_bottom.getObj("scwin").setReturnValue("type : "+ type);
        wf_body_bottom.getObj("scwin").setReturnValue("value : "+ value);
    }
}
